(()=>{'use strict';let playing=null,audio=null,generation=0;const clips={style:{iran:'style-iran',classic:'style-classic',pop:'style-pop',rhythm:'style-rhythm',electronic:'style-electronic'},sound:{pluck:'sound-pluck',bow:'sound-bow',keys:'sound-keys',wind:'sound-wind',beat:'sound-beat',voice:'sound-voice'},goal:{accompany:'goal-accompany',melody:'goal-melody',ensemble:'goal-ensemble',rhythm:'goal-rhythm',compose:'goal-compose',sing:'goal-sing'},touch:{strings:'sound-pluck',bow:'sound-bow',keys:'sound-keys',breath:'sound-wind',hands:'sound-beat',digital:'style-electronic'}};const status=text=>{const el=document.getElementById('guide-audio-status');if(el)el.textContent=text};function stop(){generation++;if(audio){audio.pause();audio.removeAttribute('src');audio.load();audio=null}if(playing){playing.classList.remove('is-playing');playing.setAttribute('aria-pressed','false');playing.textContent='▶ بشنو';playing.disabled=false;playing=null}}async function play(button,q,value){if(playing===button){stop();status('پخش متوقف شد.');return}stop();const clip=clips[q]?.[value];if(!clip)return;const run=generation;playing=button;audio=new Audio('audio/guide-clips/'+clip+'.mp3');audio.preload='none';const current=audio;button.textContent='■ توقف';button.classList.add('is-playing');button.setAttribute('aria-pressed','true');current.onended=()=>{if(run===generation){stop();status('پایان نمونه؛ دوباره بشنو یا گزینه را انتخاب کن.')}};current.onerror=()=>{if(run===generation){stop();status('صدا بارگذاری نشد؛ دوباره امتحان کن.')}};try{await current.play();if(run!==generation){current.pause();return}status('در حال پخش نمونهٔ موسیقی؛ برای توقف دوباره بزن.')}catch{if(run===generation){stop();status('پخش انجام نشد؛ اتصال و صدای دستگاه را بررسی کن.')}}}window.HezaravaAudio={stop,available:(q,v)=>!!clips[q]?.[v],label:()=> 'نمونهٔ موسیقی',bind:(root,q)=>root.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>play(b,q,b.dataset.preview))};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});window.addEventListener('pagehide',stop)})();
